parameters.jsCode:
const body = $json.body ?? {};

const question = String(body.question ?? "").trim();

if (!question) {
  throw new Error("Question is required.");
}

return [
  {
    json: {
      question,
      user_id: body.user_id ?? null,
      user_email: body.user_email ?? null,
    },
  },
];

const items = $input.all();

const chunks = items
  .map((item) => item.json.document || item.json)
  .filter((doc) => doc && doc.pageContent);

const policyContext = chunks.length
  ? chunks
      .map((doc, i) => `[Policy excerpt ${i + 1}]\n${doc.pageContent}`)
      .join("\n\n")
  : "";

const q = $('Extract Passenger Question').first().json;

return [
  {
    json: {
      question: q.question,
      user_id: q.user_id,
      user_email: q.user_email,
      policy_context: policyContext,
      policy_context_found: chunks.length > 0,
    },
  },
];

